"""Islamiat (Ikhtiari) XII PDF76: pp.142–143 — ahadith 47 (explanation), 48. Run: python class12_iski_page076.py"""
from class12_iski_common import BOOK, Builder, rec, P, AR


def p76():
    b = Builder()
    b.h('Explanation', 'تشریح', 'تشریح')
    P(b, [('In this blessed hadith the rights of animals are mentioned, and for those people who adopt a harsh attitude towards them, the warning of severe punishment has been given. In the previous hadith such a person was mentioned who gave water to a thirsty dog and was forgiven. In this blessed hadith such a woman is mentioned who tied up a cat and did not give it anything to eat or drink either, because of which it died. On the basis of this crime Allah the Exalted sent this woman to Hell.', 'اس حدیثِ مبارکہ میں جانوروں کے حقوق کا ذکر ہے اور جو لوگ ان کے بارے میں سخت رویہ رکھتے ہیں ان کے لیے سخت عذاب کی وعید سنائی گئی ہے۔ گزشتہ حدیث میں ایک ایسے شخص کا ذکر ہوا ہے جس نے ایک پیاسے کتے کو پانی پلایا تھا اور اسے بخش دیا گیا تھا۔ اس حدیثِ مبارکہ میں ایک ایسی عورت کا ذکر ہے جس نے بلی کو باندھ دیا اور اسے کچھ کھانے پینے کے لیے بھی نہ دیا، جس کی وجہ سے وہ مر گئی۔ اس جرم کی بنا پر اللہ تعالیٰ نے اس عورت کو جہنم رسید کر دیا۔', 'په دې مبارک حدیث کې د څارویو د حقونو یادونه ده، او کوم خلک چې د هغوی په اړه سخت چلند لري، هغوی ته د سخت عذاب ګواښ اورول شوی. په تېر حدیث کې د داسې یو کس یادونه وشوه چې تږي سپي ته یې اوبه ورکړې او وبښل شو. په دې مبارک حدیث کې د داسې یوې ښځې یادونه ده چې پیشو یې وتړله او هېڅ خواړه او اوبه یې هم ورنه کړل، چې له امله یې مړه شوه. د دې جرم پر بنسټ الله تعالی دا ښځه دوزخ ته ولېږله.'),
          ('Islam has fixed the rights of every living being. Even about animals and birds urging has been made that they be treated with kindness and mercy. They too are the creation of Allah. The Noble Prophet ﷺ has commanded gentle treatment of animals. Only as much work should be taken from them as is their capacity, and proper arrangement should be made for their food and drink. Moreover such merciless treatment should never be done with them from which harm reaches them, otherwise the grip of Allah is very severe.', 'اسلام نے ہر جاندار کے حقوق مقرر کیے ہیں۔ جانوروں اور پرندوں تک کے بارے میں تلقین کی گئی ہے کہ ان کے ساتھ مہربانی اور رحم کا برتاؤ کریں۔ وہ بھی اللہ کی مخلوق ہیں۔ نبی کریم صلی اللہ علیہ وآلہٖ وسلم نے جانوروں کے ساتھ نرمی کا برتاؤ کرنے کا حکم دیا ہے۔ ان سے اتنا ہی کام لینا چاہیے جتنی ان کی سکت ہو اور ان کے کھانے پینے کا مناسب بندوبست کرنا چاہیے۔ نیز ان کے ساتھ ایسا بے رحمانہ سلوک کبھی نہ کریں جس سے انہیں نقصان پہنچے ورنہ اللہ کی پکڑ بڑی سخت ہے۔', 'اسلام د هر ژوندي حقونه ټاکلي. حتی د څارویو او مرغانو په اړه سپارښتنه شوې چې ورسره د مهربانۍ او رحم چلند وشي. هغوی هم د الله مخلوق دي. نبي کریم ﷺ له څارویو سره د نرم چلند حکم کړی. له هغوی باید هومره کار واخیستل شي څومره چې یې توان وي، او د خوړو او څښاک مناسب انتظام یې وشي. همداسې هېڅکله ورسره داسې بې‌رحمه چلند مه کوئ چې زیان ورته ورسېږي، ګنې د الله نیول ډېر سخت دي.')])
    b.h('Hadith no. 48', 'حدیث نمبر 48', 'حدیث نمبر ۴۸')
    AR(b, 'عَنْ اَبِيْ سَعِيْدِ الْخُدْرِيِّ رَضِيَ اللّٰهُ عَنْهُ قَالَ: جَآءَتِ امْرَاَةٌ اِلٰى رَسُوْلِ اللّٰهِ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ فَقَالَتْ: يَا رَسُوْلَ اللّٰهِ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ ذَهَبَ الرِّجَالُ بِحَدِيْثِكَ، فَاجْعَلْ لَنَا مِنْ نَّفْسِكَ يَوْمًا نَّاْتِيْكَ فِيْهِ تُعَلِّمُنَا مِمَّا عَلَّمَكَ اللّٰهُ، فَقَالَ: "اِجْتَمِعْنَ فِيْ يَوْمِ كَذَا وَكَذَا، فِيْ مَكَانِ كَذَا وَكَذَا" فَاجْتَمَعْنَ، فَاَتَاهُنَّ رَسُوْلُ اللّٰهِ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ فَعَلَّمَهُنَّ مِمَّا عَلَّمَهُ اللّٰهُ ثُمَّ قَالَ: "مَا مِنْكُمُ امْرَاَةٌ تُقَدِّمُ بَيْنَ يَدَيْهَا مِنْ وَّلَدِهَا ثَلٰثَةً اِلَّا كَانَ لَهَا حِجَابًا مِّنَ النَّارِ" فَقَالَتِ امْرَاَةٌ مِّنْهُنَّ يَا رَسُوْلَ اللّٰهِ! اِثْنَيْنِ؟ قَالَ: فَاَعَادَتْهَا مَرَّتَيْنِ ثُمَّ قَالَ: "وَاثْنَيْنِ، وَاثْنَيْنِ، وَاثْنَيْنِ"', 'صحیح مسلم و صحیح البخاری')
    r1 = rec(b, 2, 142, 76, [142])
    t = Builder()
    t.p('Translation: Hazrat Abu Sa\'id al-Khudri (may Allah be pleased with him) says: a woman came to the Noble Prophet ﷺ. She began to say: O Messenger of Allah ﷺ, the men have taken your ahadith (and we have remained deprived); fix some day from your side for us so that we may come on that day and learn from you ﷺ that which Allah the Exalted has taught you ﷺ. So the Noble Prophet ﷺ said: gather on such-and-such day at such-and-such place. So they gathered. Then the Noble Prophet ﷺ came to them and taught them what Allah had taught him ﷺ. Then he said: whichever woman among you sends ahead of her three young children, certainly they will become a veil for her from Hell. One woman among them said: O Messenger of Allah, two as well? That woman said this twice. Then he ﷺ said: and two as well, and two as well, and two as well.', 'ترجمہ: حضرت ابو سعید الخدری رضی اللہ تعالیٰ عنہ فرماتے ہیں: ایک عورت نبی کریم صلی اللہ علیہ وآلہٖ وسلم کے پاس آئی۔ کہنے لگی اے اللہ کے رسول صلی اللہ علیہ وآلہٖ وسلم مردوں نے آپ صلی اللہ علیہ وآلہٖ وسلم کی حدیثیں لے لیں (ہم محروم رہ گئیں) ہمارے لیے بھی اپنی طرف سے کوئی دن مقرر کریں تاکہ ہم اس دن آئیں اور آپ صلی اللہ علیہ وآلہٖ وسلم سے وہ سیکھیں جو اللہ تعالیٰ نے آپ صلی اللہ علیہ وآلہٖ وسلم کو سکھایا ہے۔ پس آپ نبی کریم صلی اللہ علیہ وآلہٖ وسلم نے فرمایا: فلاں دن اور فلاں جگہ جمع ہو جائیں پس وہ جمع ہو گئیں۔ چنانچہ ان کے پاس نبی کریم صلی اللہ علیہ وآلہٖ وسلم تشریف لائے پس اُن کو وہ سکھایا جو اللہ نے آپ صلی اللہ علیہ وآلہٖ وسلم کو سکھایا پھر فرمایا: تم میں سے جس عورت نے اپنے آگے تین چھوٹے بچے بھیجے تو بے شک وہ اس کے لیے جہنم سے پردہ بن جائیں گے۔ ان میں سے ایک عورت نے کہا: یا رسول اللہ: دو بھی؟ اس عورت نے یہ بات دو مرتبہ کہی۔ پھر آپ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا! اور دو بھی، اور دو بھی، اور دو بھی۔', 'ژباړه: حضرت ابو سعید خدري رضي الله عنه وايي: یوه ښځه نبي کریم ﷺ ته راغله. ویې ویل: اې د الله رسوله ﷺ، نارینه وو ستا احادیث واخیستل (او موږ بې‌برخې پاتې شوو)؛ زموږ لپاره هم له خپل لوري کومه ورځ وټاکه تر څو په هغه ورځ راشو او له تا ﷺ هغه زده کړو چې الله تعالی تا ﷺ ته ښوولي. نو نبي کریم ﷺ وفرمایل: په فلانۍ ورځ او فلاني ځای کې راټولې شئ. نو راټولې شوې. بیا نبي کریم ﷺ ورته راغی او هغه یې ورته وښوول چې الله هغه ﷺ ته ښوولي و. بیا یې وفرمایل: ستاسو له منځه چې کومې ښځې خپل درې کوچني ماشومان مخکې ولېږل، بې‌شکه هغوی به یې لپاره له دوزخه پرده شي. یوې ښځې وویل: اې د الله رسوله، دوه هم؟ هغې ښځې دا خبره دوه ځله وکړه. بیا هغه ﷺ وفرمایل: او دوه هم، او دوه هم، او دوه هم.')
    t.h('Explanation', 'تشریح', 'تشریح')
    t.p('In this blessed hadith the education of women is mentioned. Moreover there is glad tidings of deliverance from Hell for such women whose three or two children died in childhood itself. Once a woman had requested him ﷺ that the men keep on learning various sciences from him ﷺ; some such arrangement should be made in which women too may present themselves to him ﷺ and benefit from the fountain of prophethood. He ﷺ granted the honour of acceptance to this woman\'s request and fixed a day for women. On that day the ladies would present themselves in his ﷺ court and gather up the goods of religion and the world. On such an occasion he ﷺ had given glad tidings to the women whose three or two children had died in childhood that those children would become a shield between them and Hell. The grief of children dying in childhood only that mother knows from whose womb they were born. In view of their griefs, he ﷺ gave them good news that they will certainly receive its recompense from Allah the Exalted.', 'اس حدیثِ مبارکہ میں عورتوں کی تعلیم کا ذکر ہے۔ نیز ایسی عورتوں کے لیے جہنم سے نجات کی خوشخبری ہے جن کے تین یا دو بچے بچپن میں ہی وفات پا گئے ہوں۔ ایک دفعہ آپ صلی اللہ علیہ وآلہٖ وسلم کے پاس ایک عورت نے درخواست کی تھی کہ مرد حضرات تو آپ صلی اللہ علیہ وآلہٖ وسلم سے مختلف علوم سیکھتے ہی رہتے ہیں کوئی ایسا انتظام ہو جائے کہ جس میں عورتیں بھی آپ صلی اللہ علیہ وآلہٖ وسلم کے پاس حاضر ہو کر چشمۂ نبوت سے فیض یاب ہوں۔ آپ صلی اللہ علیہ وآلہٖ وسلم نے اس عورت کی درخواست کو شرفِ قبولیت بخشا اور عورتوں کے لیے ایک دن مقرر فرما دیا۔ اس دن خواتین آپ صلی اللہ علیہ وآلہٖ وسلم کی بارگاہ میں حاضر ہوتیں اور دین و دنیا کی بھلائیاں سمیٹ کر لے جاتیں۔ ایسے موقع پر ہی آپ صلی اللہ علیہ وآلہٖ وسلم نے ان عورتوں کو خوشخبری دی تھی جن کے تین یا دو بچے بچپن میں فوت ہو گئے ہوں کہ وہ بچے جہنم اور ان کے درمیان ڈھال بن جائیں گے۔ اولاد کے بچپن میں فوت ہو جانے کا دکھ وہ ماں ہی جانتی ہے جس کی کوکھ سے انہوں نے جنم لیا ہوتا ہے۔ آپ صلی اللہ علیہ وآلہٖ وسلم نے ان کے دکھوں کے پیشِ نظر انہیں اچھی خبر سنائی کہ اس کا بدلہ اللہ تعالیٰ کے ہاں انہیں ضرور ملے گا۔', 'په دې مبارک حدیث کې د ښځو د زده‌کړې یادونه ده. همداسې د داسې ښځو لپاره له دوزخه د نجات زېری دی چې درې یا دوه ماشومان یې په ماشومتوب کې مړه شوي وي. یو ځل یوې ښځې هغه ﷺ ته غوښتنه وکړه چې نارینه خو له هغه ﷺ بېلابېل علوم زده کوي؛ داسې انتظام دې وشي چې ښځې هم هغه ﷺ ته حاضرې شي او د نبوت له چینې ګټه واخلي. هغه ﷺ د دې ښځې غوښتنه ومنله او د ښځو لپاره یې یوه ورځ وټاکله. په هغه ورځ به ښځې د هغه ﷺ دربار ته حاضرېدې او د دین او دنیا ښېګڼې به یې راټولولې. په همداسې یوه موقع هغه ﷺ هغو ښځو ته زېری ورکړ چې درې یا دوه ماشومان یې په ماشومتوب کې مړه شوي وي، چې هغه ماشومان به د دوی او دوزخ ترمنځ ډال شي. د ماشومتوب کې د اولاد د مړینې درد یوازې هغه مور پېژني چې له ګېډې یې زېږېدلي وي. هغه ﷺ د هغوی د دردونو په پام کې نیولو ورته ښه خبر واوراوه چې بدله به یې له الله تعالی سره خامخا ومومي.')
    BOOK.save(76, [(2, r1), (2, rec(t, 2, 143, 76, [143]))], issues=[{'id': 'iski12-pdf076', 'unit': 2, 'printedPage': 142,
               'description': 'A keyboard visible at the top of the p.142 scan and neighbouring book covers at the left edge of p.143 excluded.'}])


if __name__ == '__main__':
    p76()
